import * as THREE from 'three';
import { OrbitControls } from './vendor/OrbitControls.js';

const $ = s => document.querySelector(s);
const defaults = {name:'新角色',gender:'female',height:50,weight:45,shoulders:45,legs:50,faceWidth:50,jaw:45,eyeSize:50,eyeSpace:50,nose:50,mouth:50,hair:'bob',clothes:'casual',skin:'#d6a17e',hairColor:'#332821',shirt:'#778f87',pants:'#343b50'};
const choices = {gender:[['female','女性'],['male','男性']],hair:[['short','利落短发'],['bob','齐耳短发'],['long','披肩长发'],['bun','高发髻'],['bald','光头']],clothes:[['casual','休闲短袖'],['formal','衬衫领带'],['sport','运动背心'],['dress','简约连衣裙']]};
const palettes = {skin:['#f1cbb2','#d6a17e','#b87c55','#86543c','#51372c'],hairColor:['#201d20','#332821','#815137','#c5a15e','#b7b9c4','#854d67'],shirt:['#778f87','#d7c8b0','#a24d54','#537892','#373c49','#bca0c2'],pants:['#343b50','#292c31','#a09380','#655850']};
const ranges = {height:['身高','较矮','较高'],weight:['体型','纤细','丰满'],shoulders:['肩宽','窄','宽'],legs:['腿长比例','短','长'],faceWidth:['脸部宽度','窄','宽'],jaw:['下颌轮廓','收窄','方正'],eyeSize:['眼睛大小','小','大'],eyeSpace:['眼间距','近','远'],nose:['鼻子大小','小','大'],mouth:['嘴唇宽度','窄','宽']};
const tabs = {body:['01 / FOUNDATION','创造独一无二的你','从轮廓开始，定义角色的基础形象。',['name','gender','height','weight','shoulders','legs','skin']],face:['02 / FEATURES','每一面，都有个性','旋转角色，查看五官与轮廓的变化。',['faceWidth','jaw','eyeSize','eyeSpace','nose','mouth']],hair:['03 / HAIRSTYLE','从头开始的风格','选择发型，再搭配喜欢的发色。',['hair','hairColor']],clothes:['04 / WARDROBE','穿出你的日常','为角色选择一套简单的穿搭。',['clothes','shirt','pants']]};
const labels={gender:'性别',hair:'发型',clothes:'服饰',skin:'肤色',hairColor:'发色',shirt:'上装颜色',pants:'下装颜色'};
let state={...defaults}, activeTab='body', currentView='full', model, renderer, scene, camera, orbit;
const stage=$('#stage');
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
function normalize(value){if(!value || typeof value!=='object' || Array.isArray(value))throw Error('无效角色');const out={...defaults};for(const key of Object.keys(defaults)){const v=value[key];if(key==='name' && typeof v==='string')out[key]=v.trim().slice(0,32)||'新角色';else if(ranges[key] && typeof v==='number' && Number.isFinite(v))out[key]=Math.max(0,Math.min(100,v));else if(choices[key] && choices[key].some(c=>c[0]===v))out[key]=v;else if(palettes[key] && typeof v==='string' && /^#[0-9a-f]{6}$/i.test(v))out[key]=v;}return out;}
function element(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function update(){ $('#display-name').textContent=state.name; buildCharacter(); }
function renderControls(){const [num,title,desc,fields]=tabs[activeTab];$('#section-number').textContent=num;$('#section-title').textContent=title;$('#section-desc').textContent=desc;$('#controls').replaceChildren();for(const key of fields){const wrap=element('div','field');const label=element('label','field-title',ranges[key]?.[0]||labels[key]||'角色名称');label.htmlFor='control-'+key;wrap.append(label);if(key==='name'){const input=element('input','name-input');input.id='control-'+key;input.maxLength=32;input.value=state.name;input.oninput=()=>{state.name=input.value;$('#display-name').textContent=state.name||'新角色';};wrap.append(input);}else if(ranges[key]){const output=element('output',null,state[key]);label.append(output);const input=element('input');input.id='control-'+key;input.type='range';input.min=0;input.max=100;input.value=state[key];input.oninput=()=>{state[key]=Number(input.value);output.textContent=input.value;update();};wrap.append(input);const ends=element('div','range-labels');ends.append(element('span',null,ranges[key][1]),element('span',null,ranges[key][2]));wrap.append(ends);}else {const box=element('div',palettes[key]?'swatches':key==='gender'?'segmented':'options');const values=palettes[key]?.map(c=>[c,c])||choices[key];for(const [value,text] of values){const button=element('button',palettes[key]?'swatch':'option',palettes[key]?undefined:text);button.classList.toggle('selected',state[key]===value);button.setAttribute('aria-label',labels[key]+' '+text);button.setAttribute('aria-pressed',String(state[key]===value));if(palettes[key])button.style.setProperty('--color',value);button.onclick=()=>{state[key]=value;update();renderControls();};box.append(button);}wrap.append(box);}$('#controls').append(wrap);}}
function material(color){return new THREE.MeshStandardMaterial({color,roughness:.75});}
function buildCharacter(){if(!scene)return;if(model){scene.remove(model);const mats=new Set();model.traverse(o=>{o.geometry?.dispose();if(o.material)mats.add(o.material);});mats.forEach(m=>m.dispose());}model=new THREE.Group();scene.add(model);
const skin=material(state.skin),hair=material(state.hairColor),shirt=material(state.shirt),pants=material(state.pants),shoe=material('#24262d'),white=material('#f7f2e9'),iris=material('#4b665b'),dark=material('#20232a'),lip=material('#a66a60');
const female=state.gender==='female';const width=.85+state.weight*.006;const shoulder=(female?.9:1.06)*(.82+state.shoulders*.004);const leg=.76+state.legs*.0025;const hips=leg+.12;const neck=hips+.72;const headY=neck+.31;
function ell(parent,mat,x,y,z,sx,sy,sz){const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),mat);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
function limb(mat,a,b,r1,r2){const va=new THREE.Vector3(...a),vb=new THREE.Vector3(...b),diff=vb.clone().sub(va);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,diff.length(),20),mat);mesh.position.copy(va).add(vb).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),diff.normalize());mesh.castShadow=true;model.add(mesh);return mesh;}
for(const s of [-1,1]){const x=s*.14*width;ell(model,shoe,x,.085,.075,.115,.085,.21);limb(pants,[x,.14,0],[x,leg*.55,0],.085*width,.105*width);ell(model,pants,x,leg*.55,0,.105*width,.115,.105*width);limb(pants,[x,leg*.55,0],[x,hips,0],.105*width,.145*width);}
ell(model,state.clothes==='dress'?shirt:pants,0,hips,0,.29*width,.22,.17*width);
ell(model,shirt,0,hips+.37,0,.27*width*shoulder,.4,.17*width);
if(female)for(const s of [-1,1])ell(model,shirt,s*.104*width,hips+.51,.108,.119*width,.12,.105);
limb(skin,[0,neck-.05,0],[0,neck+.13,0],.085,.078);
for(const s of [-1,1]){const a=[s*.27*width*shoulder,neck-.13,0],b=[s*(.38*width*shoulder),hips+.35,0],c=[s*(.43*width*shoulder),hips+.03,.025];ell(model,shirt,...a,.125*width,.14,.135*width);limb(state.clothes==='sport'?skin:shirt,a,b,.085*width,.105*width);ell(model,skin,...b,.08*width,.09,.08*width);limb(skin,b,c,.059*width,.079*width);ell(model,skin,c[0],c[1]-.07,c[2],.07,.105,.055);}
if(state.clothes==='dress'){const skirt=new THREE.Mesh(new THREE.CylinderGeometry(.235*width,.4*width,.56,32),shirt);skirt.position.y=hips-.18;skirt.castShadow=true;model.add(skirt);}
if(state.clothes==='formal'){for(const s of [-1,1]){const collar=ell(model,white,s*.064,neck-.12,.165,.056,.1,.025);collar.rotation.z=s*-.5;}ell(model,dark,0,neck-.31,.18,.034,.16,.023);}
const head=new THREE.Group();head.position.y=headY;model.add(head);const fw=.19*(.8+state.faceWidth*.004);ell(head,skin,0,0,0,fw,.27,.185);ell(head,skin,0,-.115,.013,fw*(.63+state.jaw*.004),.15,.163);
for(const s of [-1,1]){ell(head,skin,s*fw,.005,0,.045,.077,.034);const x=s*(.065+state.eyeSpace*.00045),ey=.024,es=.8+state.eyeSize*.005;ell(head,white,x,ey,.166,.047*es,.026*es,.022);ell(head,iris,x,ey,.185,.018*es,.019*es,.012);ell(head,dark,x,ey,.195,.009*es,.012*es,.006);ell(head,white,x-.006,ey+.008,.201,.004,.004,.003);const brow=ell(head,hair,x,.079,.162,.051,.01,.013);brow.rotation.z=s*-.08;}
ell(head,skin,0,-.028,.188,.023+state.nose*.00022,.047,.023+state.nose*.0005);ell(head,lip,0,-.108,.165,.035+state.mouth*.00055,.012,.016);
if(state.hair!=='bald'){const cap=new THREE.Mesh(new THREE.SphereGeometry(1,32,20,0,Math.PI*2,0,1.43),hair);cap.scale.set(fw+ .024,.286,.205);cap.position.y=.012;head.add(cap);cap.castShadow=true;for(const s of [-1,1])ell(head,hair,s*(fw-.013),.05,-.06,.065,state.hair==='short'?.12:.23,.15);for(let i=0;i<5;i++){const bang=ell(head,hair,(i-2)*fw*.36,.16-Math.abs(i-2)*.013,.13,.06,.115,.084);bang.rotation.z=-.35;}if(state.hair==='long')ell(head,hair,0,-.18,-.11,fw+.04,.36,.12);if(state.hair==='bob')ell(head,hair,0,-.04,-.115,fw+.028,.245,.12);if(state.hair==='bun')ell(head,hair,0,.295,-.07,.115,.12,.105);}
const scale=.88+state.height*.0024;model.scale.setScalar(scale);}
function setView(view){currentView=view;if(!camera)return;const h=(.88+state.height*.0024);if(view==='face'){camera.position.set(0,2.05*h,1.22);orbit.target.set(0,1.98*h,0);}else{camera.position.set(0,1.6,4.5);orbit.target.set(0,1.12,0);}orbit.update();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));}
try{scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,1,.05,100);renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;stage.append(renderer.domElement);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.enablePan=false;orbit.minDistance=.65;orbit.maxDistance=7;orbit.maxPolarAngle=Math.PI*.52;scene.add(new THREE.HemisphereLight('#e4eeff','#4b4150',2.5));const key=new THREE.DirectionalLight('#ffe6c7',3.1);key.position.set(3,5,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);scene.add(key);const rim=new THREE.DirectionalLight('#a6c4ff',2);rim.position.set(-3,3,-2);scene.add(rim);const floor=new THREE.Mesh(new THREE.CylinderGeometry(.8,.84,.08,64),material('#434b55'));floor.position.y=-.045;floor.receiveShadow=true;scene.add(floor);new ResizeObserver(()=>{const {width,height}=stage.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}).observe(stage);setView('full');renderer.setAnimationLoop(()=>{orbit.update();renderer.render(scene,camera);});}catch(error){console.error(error);$('#webgl-error').hidden=false;}
const storageKey='charabuilder.characters.v1';
function readArchive(){const raw=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(raw))throw Error('档案格式错误');return raw;}
function showArchive(){try{const rows=readArchive();$('#saved-list').replaceChildren();if(!rows.length)$('#saved-list').append(element('p',null,'还没有角色，点击「保存角色」创建档案。'));for(const row of rows){const div=element('div','save-row'),name=element('span',null,row.character.name);name.append(element('small',null,new Date(row.savedAt).toLocaleString()));const load=element('button',null,'载入'),del=element('button',null,'删除');load.onclick=()=>{state=normalize(row.character);update();renderControls();setView(currentView);$('#archive').close();toast('角色已载入');};del.onclick=()=>{if(!confirm('删除这份角色档案？'))return;try{localStorage.setItem(storageKey,JSON.stringify(readArchive().filter(r=>r.id!==row.id)));showArchive();}catch{toast('无法更新档案');}};div.append(name,load,del);$('#saved-list').append(div);}if(!$('#archive').open)$('#archive').showModal();}catch{toast('无法读取浏览器档案，请检查浏览器存储设置');}}
$('#save').onclick=()=>{try{state=normalize(state);const rows=readArchive();rows.unshift({id:crypto.randomUUID(),savedAt:new Date().toISOString(),character:{...state}});localStorage.setItem(storageKey,JSON.stringify(rows));toast('角色已保存到本机档案');}catch{toast('保存失败，请导出 JSON 文件备份');}};
$('#load').onclick=showArchive;$('#close').onclick=()=>$('#archive').close();
$('#export').onclick=()=>{const data={format:'charabuilder',version:1,character:normalize(state)};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=element('a');a.href=url;a.download=(state.name||'character').replace(/[\\/:*?"<>|]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('过大');const data=JSON.parse(await file.text());if(data.format!=='charabuilder'||data.version!==1||!data.character)throw Error('格式');state=normalize(data.character);update();renderControls();setView(currentView);$('#archive').close();toast('角色文件已导入，可继续编辑');}catch{toast('导入失败：请选择有效的 CharaBuilder JSON 文件');}finally{e.target.value='';}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderControls();setView(activeTab==='face'||activeTab==='hair'?'face':'full');});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#reset-view').onclick=()=>setView(currentView);$('#rotate').onclick=()=>{if(!orbit)return;orbit.autoRotate=!orbit.autoRotate;$('#rotate').setAttribute('aria-pressed',String(orbit.autoRotate));$('#rotate').classList.toggle('selected',orbit.autoRotate);};$('#reset').onclick=()=>{if(!confirm('重置当前未保存的调整？'))return;state={...defaults};update();renderControls();setView('full');};$('#random').onclick=()=>{for(const key of Object.keys(ranges))state[key]=Math.round(20+Math.random()*60);for(const [key,values] of Object.entries(choices))state[key]=values[Math.floor(Math.random()*values.length)][0];for(const [key,values] of Object.entries(palettes))state[key]=values[Math.floor(Math.random()*values.length)];update();renderControls();setView(currentView);};
update();renderControls();
